import React, { useEffect, useRef } from 'react';

const PhotoFrame = ({ photo, userName, location }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    if (photo && canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      const img = new Image();

      img.onload = () => {
        // High quality canvas
        canvas.width = 800;
        canvas.height = 1000;

        // Background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // --- DRAW DECORATIVE CORNERS ---
        const drawCorners = () => {
          ctx.save();

          // Dark Green Fill
          ctx.fillStyle = '#005a32';

          // Top Left
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.lineTo(250, 0);
          ctx.quadraticCurveTo(50, 50, 0, 250);
          ctx.fill();

          // Top Right
          ctx.beginPath();
          ctx.moveTo(canvas.width, 0);
          ctx.lineTo(canvas.width - 250, 0);
          ctx.quadraticCurveTo(canvas.width - 50, 50, canvas.width, 250);
          ctx.fill();

          // Gold accents
          ctx.strokeStyle = '#d4af37';
          ctx.lineWidth = 8;

          // Top Left Gold
          ctx.beginPath();
          ctx.moveTo(260, 0);
          ctx.quadraticCurveTo(60, 60, 0, 260);
          ctx.stroke();

          // Top Right Gold
          ctx.beginPath();
          ctx.moveTo(canvas.width - 260, 0);
          ctx.quadraticCurveTo(canvas.width - 60, 60, canvas.width, 260);
          ctx.stroke();

          // Bottom Curves (Large)
          ctx.fillStyle = '#005a32';
          ctx.beginPath();
          ctx.moveTo(0, canvas.height);
          ctx.lineTo(0, canvas.height - 150);
          ctx.bezierCurveTo(200, canvas.height - 250, canvas.width - 200, canvas.height - 250, canvas.width, canvas.height - 150);
          ctx.lineTo(canvas.width, canvas.height);
          ctx.fill();

          // Bottom Gold Accent
          ctx.beginPath();
          ctx.moveTo(0, canvas.height - 165);
          ctx.bezierCurveTo(200, canvas.height - 265, canvas.width - 200, canvas.height - 265, canvas.width, canvas.height - 165);
          ctx.stroke();

          ctx.restore();
        };

        drawCorners();

        const centerX = canvas.width / 2;

        // --- TOP LOGO AREA ---
        // 100 Years Celebration
        ctx.textAlign = 'center';
        ctx.fillStyle = '#005a32';
        ctx.font = 'bold 80px "Times New Roman", serif';
        ctx.fillText('100', centerX, 150);

        ctx.font = 'bold 20px Arial, sans-serif';
        ctx.fillStyle = '#d4af37';
        ctx.fillText('YEARS', centerX, 175);

        ctx.font = '16px Arial, sans-serif';
        ctx.letterSpacing = '4px';
        ctx.fillText('CELEBRATION', centerX, 200);

        // School Name
        ctx.fillStyle = '#005a32';
        ctx.font = 'bold 42px "Times New Roman", serif';
        ctx.fillText(location || 'AKESP School', centerX, 270);

        // Separator under school
        ctx.strokeStyle = '#d4af37';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(centerX - 150, 285);
        ctx.lineTo(centerX + 150, 285);
        ctx.stroke();

        // --- CIRCULAR PHOTO ---
        const photoY = 480;
        const radius = 160;

        // Photo Border (Gold & Green)
        ctx.save();
        ctx.beginPath();
        ctx.arc(centerX, photoY, radius + 15, 0, Math.PI * 2);
        ctx.strokeStyle = '#005a32';
        ctx.lineWidth = 10;
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(centerX, photoY, radius + 5, 0, Math.PI * 2);
        ctx.strokeStyle = '#d4af37';
        ctx.lineWidth = 4;
        ctx.stroke();

        // Clip and Draw Image
        ctx.beginPath();
        ctx.arc(centerX, photoY, radius, 0, Math.PI * 2);
        ctx.clip();

        // Cover aspect ratio
        const aspect = img.width / img.height;
        let drawW, drawH, drawX, drawY;
        if (aspect > 1) {
          drawH = radius * 2;
          drawW = drawH * aspect;
          drawX = centerX - drawW / 2;
          drawY = photoY - radius;
        } else {
          drawW = radius * 2;
          drawH = drawW / aspect;
          drawX = centerX - radius;
          drawY = photoY - drawH / 2;
        }
        ctx.drawImage(img, drawX, drawY, drawW, drawH);
        ctx.restore();

        // Small Ornaments around photo
        ctx.fillStyle = '#d4af37';
        const drawDiamond = (x, y) => {
          ctx.beginPath();
          ctx.moveTo(x, y - 10);
          ctx.lineTo(x + 10, y);
          ctx.lineTo(x, y + 10);
          ctx.lineTo(x - 10, y);
          ctx.fill();
        };
        drawDiamond(centerX - radius - 40, photoY);
        drawDiamond(centerX + radius + 40, photoY);

        // --- BANNER ---
        const bannerY = 680;
        ctx.save();
        ctx.fillStyle = '#005a32';
        // Banner Shape
        ctx.beginPath();
        ctx.moveTo(centerX - 220, bannerY - 30);
        ctx.lineTo(centerX + 220, bannerY - 30);
        ctx.lineTo(centerX + 240, bannerY);
        ctx.lineTo(centerX + 220, bannerY + 30);
        ctx.lineTo(centerX - 220, bannerY + 30);
        ctx.lineTo(centerX - 240, bannerY);
        ctx.closePath();
        ctx.fill();

        // Banner Border
        ctx.strokeStyle = '#d4af37';
        ctx.lineWidth = 3;
        ctx.stroke();

        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 36px "Times New Roman", serif';
        ctx.fillText('• Gift of Reading •', centerX, bannerY + 12);
        ctx.restore();

        // --- BOTTOM DETAILS ---
        ctx.fillStyle = '#64748b';
        ctx.font = 'italic 18px Arial, sans-serif';
        ctx.fillText('Presented by', centerX, 750);

        ctx.fillStyle = '#005a32';
        ctx.font = 'bold 24px Arial, sans-serif';
        ctx.fillText(location || 'AKESP School', centerX, 785);

        // Final Name Ornament
        ctx.fillStyle = '#005a32';
        ctx.font = 'bold 48px "Times New Roman", serif';
        ctx.fillText(userName.toLowerCase(), centerX, 870);

        // Name side ornaments
        ctx.fillStyle = '#d4af37';
        ctx.font = '24px Arial';
        ctx.fillText('❧', centerX - (userName.length * 15) - 40, 865);
        ctx.fillText('☙', centerX + (userName.length * 15) + 40, 865);

        // Bottom Logo
        ctx.font = '40px serif';
        ctx.fillText('📖', centerX, canvas.height - 40);
      };

      img.src = URL.createObjectURL(photo);
    }
  }, [photo, userName, location]);

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement('a');
    link.download = `reading-frame-${userName.replace(/\s+/g, '-')}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  return (
    <div style={{ textAlign: 'center', marginTop: '30px' }}>
      <div style={{ 
        display: 'inline-block',
        background: 'white',
        padding: '20px',
        borderRadius: '24px',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)',
        border: '1px solid #f1f5f9'
      }}>
        <h3 style={{ 
          marginBottom: '20px', 
          color: '#0f172a', 
          fontSize: '1.25rem',
          fontWeight: 800 
        }}>
          Your Personalized Reading Frame
        </h3>
        <canvas 
          ref={canvasRef} 
          style={{ 
            maxWidth: '100%', 
            width: '450px',
            height: 'auto',
            borderRadius: '12px',
            boxShadow: '0 10px 30px rgba(0,0,0,0.05)'
          }}
        />
        <div style={{ marginTop: '24px' }}>
          <button 
            onClick={handleDownload} 
            className="auth-btn-next"
            style={{ margin: '0 auto', width: 'auto', padding: '12px 32px' }}
          >
            📥 Download Frame
          </button>
        </div>
      </div>
    </div>
  );
};

export default PhotoFrame;
